HEARTBEAT_INTERVAL = 2      # seconds between heartbeats sent by a worker
TIMEOUT = 8                 # seconds of silence before a worker is declared dead

def worker_loop(worker_id, manager):
    while True:
        manager.send_heartbeat(worker_id, timestamp=now())
        sleep(HEARTBEAT_INTERVAL)

def manager_sweep(last_seen, active_workers, task_table):
    deadline = now() - TIMEOUT
    for worker_id in list(active_workers):
        if last_seen[worker_id] < deadline:
            active_workers.remove(worker_id)
            orphaned = task_table.tasks_in_progress_for(worker_id)
            for task in orphaned:
                task.mark_pending()
                scheduler.reassign(task)
            log_failure(worker_id)

