const HEARTBEAT_INTERVAL_MS = 2000;
const TIMEOUT_MS = 8000;

function workerLoop(workerId, manager) {
  setInterval(() => {
    manager.sendHeartbeat(workerId, Date.now());
  }, HEARTBEAT_INTERVAL_MS);
}

function managerSweep(lastSeen, activeWorkers, taskTable) {
  const deadline = Date.now() - TIMEOUT_MS;
  for (const workerId of [...activeWorkers]) {
    if (lastSeen[workerId] < deadline) {
      activeWorkers.delete(workerId);
      const orphaned = taskTable.tasksInProgressFor(workerId);
      for (const task of orphaned) {
        task.markPending();
        scheduler.reassign(task);
      }
      logFailure(workerId);
    }
  }
}
